INSERT INTO account_credentials (
    account_id, credential_type, encryption_algorithm, encrypted_payload,
    initialization_vector, key_version, expires_at, last_verified_at,
    verification_error, is_active, metadata, created_at, updated_at
) VALUES (
    #{accountId}, #{credentialType}, #{encryptionAlgorithm}, #{encryptedPayload},
    #{initializationVector}, #{keyVersion}, #{expiresAt}, #{lastVerifiedAt},
    #{verificationError}, #{isActive}, #{metadata,typeHandler=com.monitor.platform.infrastructure.mybatis.handler.JsonbStringTypeHandler},
    #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM account_credentials
WHERE account_id = #{accountId}
  AND credential_type = #{credentialType}
  AND is_active = TRUE
LIMIT 1

mapper.update:
UPDATE account_credentials
SET is_active = FALSE,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND credential_type = #{credentialType}
  AND is_active = TRUE
